        this.intervalMs = intervalMs;
        this.healthy = true;
        this.timer = null;
    }

    start() {
        if (this.timer) {
            return;
        }
        this.timer = setInterval(async () => {
            await this.client.ping();
            this.healthy = true;
        }, this.intervalMs);
    }

    stop() {
