     }
     return rows;
 }

 function topThree(entries) {
     return rankRows(entries).slice(0, 3);
 }

 function totalPoints(entries) {
     return entries.reduce((sum, entry) => sum + entry.points, 0);
 }

 module.exports = { rankRows, topThree, totalPoints };

