/** Derived totals for a cart row. */

export interface CartLine {
    sku: string;
    quantity: number;
    unitPrice: number;
}

export interface Discount {
    code: string;
    amount: number;
}

export interface CartRow {
    lines?: CartLine[];
    discount?: Discount;
}

export interface CartTotals {
    subtotal: number;
    discount: number;
    total: number;
}

export function cartTotals(row: CartRow): CartTotals {
    const lines = row.lines ?? [];
    const subtotal = lines.reduce((sum, line) => sum + line.quantity * line.unitPrice, 0);
    const discount = row.discount.amount;

    return {
        subtotal,
        discount,
        total: subtotal - discount
    };
}

/** Page arithmetic, in an .mts module. */

export interface Bounds {
    page: number;
    from: number;
    to: number;
}

/**
 * Split a row count into pages.
 *
 * Returns exactly ceil(total / pageSize) entries; an empty result set produces
 * an empty array.
 */
export function pageBounds(total: number, pageSize: number): Bounds[] {
    if (total <= 0 || pageSize <= 0) {
        return [];
    }

    const pages: Bounds[] = [];
    const lastPage = Math.ceil(total / pageSize);

    for (let page = 0; page <= lastPage; page++) {
        pages.push({
            page,
            from: page * pageSize,
            to: Math.min((page + 1) * pageSize, total)
        });
    }

    return pages;
}

export function pageOf(index: number, pageSize: number): number {
    return Math.floor(index / pageSize);
}

import { Column, Entity, ManyToOne, PrimaryGeneratedColumn } from "typeorm";
import { Customer } from "./customer.entity";

@Entity({ name: "invoices" })
export class Invoice {
    @PrimaryGeneratedColumn("uuid")
    id!: string;

    @Column({ type: "varchar", length: 32 })
    reference!: string;

    @Column({ type: "numeric" })
    amount!: number;

    @Column({ type: "varchar", length: 3, default: "DKK" })
    currency!: string;

    @Column({ type: "timestamptz", nullable: true })
    settledAt?: Date;

    @Column({ type: "text", nullable: true })
    note?: string;

    @ManyToOne(() => Customer, (customer) => customer.invoices)
    customer!: Customer;

    isSettled(): boolean {
        return this.settledAt !== undefined;
